INSERT INTO `t_sys_param` VALUES ('100107', '404', 'voiceChtype', '声纹接收声道设置', '0', '0：默认多声道支持 1：强制单声道，多个通道输出多个文件 -1：强制单声道，多个通道声音写入到一个文件 -2：强制单声道，通道1写完写通道2', '{\"rule\":\"^-?[0-9]\",\"msg\":\"请输入-9~9的整数\"}');
